sleep 3; echo UFS_READONLY_BEGIN; cat /proc/partitions; for node in /sys/class/block/sd*; do dev=/dev/${node##*/}; blockdev --setro "$dev"; done; for node in /sys/class/block/sd*; do name=$(sed -n 's/^PARTNAME=//p' "$node/uevent"); case "$name" in boot_a|init_boot_a|vendor_boot_a|recovery_a|dtbo_a|vbmeta_a|vbmeta_system_a|vbmeta_vendor_a) dev=/dev/${node##*/}; echo "PARTITION $name $dev"; blockdev --getsize64 "$dev"; blockdev --getro "$dev"; sha256sum "$dev";; esac; done; echo UFS_READONLY_END
